import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"


class PriceServiceUnavailable(RuntimeError):
    """Raised when the internal price service cannot be reached."""


def get_price(sku: str) -> float:
    """Fetch the live price for one SKU from the internal price service.

    No canned prices: values always come from the service. If the service
    cannot be reached (DNS failure, connection error, HTTP error), we raise
    PriceServiceUnavailable instead of guessing.
    """
    try:
        with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
            return float(json.load(r)["price"])
    except (urllib.error.URLError, OSError) as e:
        raise PriceServiceUnavailable(
            f"could not fetch price for {sku!r} from {BASE}: {e}"
        ) from e


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
